fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let len = a.len();
    
    if len <= 1 {
        // For empty or single-element arrays, return two empty arrays
        // This satisfies: 
        // - Concatenation reconstructs original (empty + empty = empty)
        // - Sum of lengths equals original length (0 + 0 = 0 or 0 + 0 = 1? Wait, need to handle single element)
        // Actually, for single element, we need to split into two shorter arrays
        // But each must be strictly shorter than original (length 1)
        // So we can split into [first] and [] or [] and [first]
        // Both are valid since [] is length 0 < 1
        if len == 0 {
            (vec![], vec![])
        } else {
            // For single element, put it in first array, second array empty
            (vec![a[0]], vec![])
        }
    } else {
        // For arrays with length > 1, split at the middle
        // This ensures both parts are strictly shorter than original
        let split_point = len / 2;
        let first = a[..split_point].to_vec();
        let second = a[split_point..].to_vec();
        
        // Both parts are non-empty and strictly shorter than original
        // since len > 1 and split_point is at least 1 and at most len-1
        (first, second)
    }
}